/* Presentation data for the deploy wizard.
 *
 * The rule this file exists to enforce: NOTHING PRICED LIVES HERE. The design
 * sandbox kept plans, add-on rates and term discounts in a catalog like this and
 * did the arithmetic in the browser. In the real system every one of those
 * numbers has an owner — Plan/GamePlan/HostingPlan/EmailPlan rows, and
 * `orderQuote` for anything derived — and a second copy here would be a second
 * pricing formula that silently drifts from the one that charges the card.
 *
 * What IS allowed here is data that has no source anywhere else and cannot be
 * wrong in a way that costs money: where a datacentre sits on a globe, which
 * artwork a service tile uses, how far a disk slider steps.
 */

/** Formatting only. Cents in, string out; no arithmetic beyond the divide. */
export const money = (cents: number) =>
  "$" + (cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

export type Region = {
  key: string;
  name: string;
  area: string;
  flag: string;
  /** Degrees, for the orthographic globe in the region step. */
  lat: number;
  lon: number;
  /**
   * The enabled nodes sitting in this region. The order intent wants a specific
   * `nodeId`, but the design asks the customer for a REGION — so the wizard
   * resolves one from here. Without this the intent would carry no node and the
   * platform's scheduler would place the server on RAM headroom alone, silently
   * ignoring the location the customer just chose.
   */
  nodeIds: string[];
  /**
   * NOMINAL round-trip, milliseconds. This is an indicative figure for the
   * region, NOT a measurement of the customer's own connection — nothing on the
   * platform probes latency per visitor. It exists so the picker can rank
   * locations sensibly; it must never be presented as "your" latency.
   */
  ms: number;
};

/* Keyed by the platform's REAL datacentre codes (lib/node-regions.ts), not an
   invented set — the wizard offers a region only where a Node actually exists,
   so the picker can never sell a location we cannot provision in. Coordinates
   are the only thing added here; the labels and flags come from the shared map
   so this file cannot drift from it. */
const COORDS: Record<string, { lat: number; lon: number; area: string; ms: number }> = {
  sgp1: { lat: 1.35, lon: 103.82, area: "Asia", ms: 12 },
  bhs1: { lat: 45.31, lon: -73.87, area: "North America", ms: 62 },
  gra1: { lat: 50.99, lon: 2.13, area: "Europe", ms: 68 },
  rbx1: { lat: 50.69, lon: 3.17, area: "Europe", ms: 68 },
  waw1: { lat: 52.23, lon: 21.01, area: "Europe", ms: 74 },
  fsn1: { lat: 50.48, lon: 12.34, area: "Europe", ms: 70 },
  nbg1: { lat: 49.45, lon: 11.08, area: "Europe", ms: 70 },

  nbg1: { lat: 49.45, lon: 11.08, area: "Europe", ms: 70 },
  hel1: { lat: 60.17, lon: 24.94, area: "Europe", ms: 76 },
  ash1: { lat: 39.04, lon: -77.49, area: "North America", ms: 52 },
  hil1: { lat: 45.52, lon: -122.98, area: "North America", ms: 48 },
};

/** Build the picker's region list from the nodes that actually exist. */
export function regionsFrom(nodes: { id: string; region: string }[]): Region[] {
  const byRegion = new Map<string, string[]>();
  for (const n of nodes) {
    if (!COORDS[n.region]) continue; // no coordinates -> cannot be drawn, so not offered
    const list = byRegion.get(n.region) ?? [];
    list.push(n.id);
    byRegion.set(n.region, list);
  }
  return [...byRegion.entries()].map(([code, nodeIds]) => {
    const c = COORDS[code];
    return {
      key: code,
      name: REGION_LABELS[code] ?? code,
      area: c.area,
      flag: REGION_COUNTRY[code] ?? "sg",
      lat: c.lat,
      lon: c.lon,
      ms: c.ms,
      nodeIds,
    };
  });
